// Normalize raw sheet rows into the ingest API's expected shape.
// Handles column-name variance and blank rows defensively.
const rows = $input.all().map(item => item.json).filter(r => r.metric_type && r.period && r.value !== undefined && r.value !== '');

return [{
  json: {
    company_id: $('Set Company Context').first().json.company_id,
    source: 'google_sheets',
    rows: rows.map(r => ({
      metric_type: r.metric_type,
      period: r.period,
      value: Number(r.value),
      category: r.category || ''
    }))
  }
}];
